"""Create a print layout from the exact Markdown report sources.

Uses Pandoc + local Chromium, with a measured two-pass PDF table of contents.
This is independent of Word automation; it never presents an unrendered DOCX as PDF.
"""
from pathlib import Path
import html,json,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/report'
sources=sorted(OUT.glob('0[1-8]_*.md'))
content='\n\n'.join(path.read_text(encoding='utf-8') for path in sources)
converted=subprocess.run(['pandoc','--from','markdown+pipe_tables+fenced_code_blocks','--to','html5'],input=content,capture_output=True,text=True,encoding='utf-8',check=True).stdout
css='''
@page {size:A4;margin:25mm 23mm 23mm 30mm}
*{box-sizing:border-box}body{font:12pt/1.28 "Times New Roman",serif;color:#111;margin:0}p{margin:0 0 7pt;text-align:justify;orphans:3;widows:3}h1{font-size:16pt;color:#14334d;line-height:1.3;break-before:page;margin:0 0 16pt}h2{font-size:14pt;color:#14334d;margin:15pt 0 8pt;break-after:avoid}h3{font-size:12pt;color:#14334d;margin:12pt 0 6pt;break-after:avoid}a{color:#14334d;text-decoration:none;overflow-wrap:anywhere}code{font:9pt Consolas,monospace;overflow-wrap:anywhere}pre{font:7.5pt/1.25 Consolas,monospace;background:#f5f7f8;padding:10pt;white-space:pre-wrap;overflow-wrap:anywhere;border-left:2pt solid #5a7c8d}pre code{font:inherit}figure{margin:12pt 0;break-inside:avoid}figure img{display:block;width:100%;max-height:17cm;object-fit:contain}figcaption{font-size:10pt;font-style:italic;text-align:center;margin-top:7pt}img{max-width:100%}table{border-collapse:collapse;width:100%;font-size:8.8pt;line-height:1.2;margin:10pt 0 14pt;table-layout:fixed}th,td{border:0.5pt solid #a8b8c2;padding:5pt 4pt;overflow-wrap:anywhere;vertical-align:top}th{background:#eaf0f4;text-align:left}thead{display:table-header-group}tr{break-inside:avoid}li{margin-bottom:5pt}.cover{min-height:23cm;text-align:center;break-after:page;padding-top:4mm}.cover p{text-align:center}.school{font-size:14pt;font-weight:bold}.cover .title{font-size:22pt;font-weight:bold;line-height:1.35;margin:35pt 0 18pt;color:#14334d}.cover .subtitle{font-size:15pt;margin-bottom:35pt}.cover .names{line-height:1.8;margin-top:30pt}.cover .state{font-size:10pt;font-weight:bold;margin:30pt 0 24pt}.front{break-before:page}.front h1{break-before:auto}.toc-entry{display:grid;grid-template-columns:minmax(0,1fr) 28pt;gap:10pt;margin-bottom:6pt;line-height:1.2;break-inside:avoid}.toc-entry.level-2{padding-left:14pt;font-size:10.5pt}.toc-entry.level-1{font-weight:bold;margin-top:10pt}.toc-number{text-align:right}.figure-list p{font-size:10pt;line-height:1.3;margin-bottom:7pt}
'''
cover='''<div class="cover"><p class="school">HỌC VIỆN CÔNG NGHỆ BƯU CHÍNH VIỄN THÔNG<br>KHOA CÔNG NGHỆ THÔNG TIN</p><p style="margin-top:35pt;font-size:17pt;font-weight:bold">BÁO CÁO TIỂU LUẬN CUỐI KỲ</p><p>PHÁT TRIỂN CÁC HỆ THỐNG THÔNG MINH</p><div class="title">DIABETES MULTI-AGENT<br>INTELLIGENT SUPPORT SYSTEM</div><p class="subtitle">Hệ đa agent hỗ trợ tìm hiểu bệnh tiểu đường</p><p class="names">Giảng viên hướng dẫn: PGS.TS. Trần Đình Quế<br>Sinh viên: Nguyễn Bá Việt Hùng — B23DCCN358<br>Nhóm 13 — Lớp 06</p><p class="state">Bản kỹ thuật Phase 08 — nghiệm thu Docker còn BLOCKED</p><p>Hà Nội, tháng 11 năm 2026</p></div>'''
front='''<section class="front"><h1>QUY ƯỚC VÀ TÌNH TRẠNG NGHIỆM THU</h1><p>Báo cáo bám cấu trúc trong hai ảnh yêu cầu của giảng viên và tham khảo hình thức tiểu luận 03. Chỉ dùng source, artifact và output thực có truy vết. Không trình bày synthetic demo như bệnh nhân thật, LLM API như tự train hoặc verifier acceptance như medical accuracy.</p><p>Bản native/HTTPS đã được kiểm chứng. Docker Compose mới parse được, chưa build/start do host không có engine/WSL; cloud hosting NOT_COMPLETED. Trạng thái cuối Phase 08 là BLOCKED, chưa xác nhận hoàn thành 100% hoặc READY_FOR_DEFENSE.</p><p>Metric lịch sử giữ timestamp/corpus/model/seed tại lần đo; Phase 08 không train lại frozen DL/RL. LLM benchmark mới có ba output được automated verifier chấp nhận trong sáu câu hỏi; hai clarification và một fallback không bị loại khỏi mẫu số.</p><h2>TÓM TẮT</h2><p>Đề tài xây dựng MAS điều phối tập trung cho giáo dục về tiểu đường, nối Prediction, Knowledge, RL Decision, Education, Verifier và Safety qua typed messages, bounded feedback và persistence. MLP được train trên Pima; graph/RAG dùng nguồn NIDDK có version; LLM inference qua Groq; Q-learning chọn action giáo dục trong simulator. Kết quả chứng minh tích hợp và audit thực hiện được, nhưng không chứng minh ưu thế phổ quát của DL/RL/MAS hoặc hiệu quả lâm sàng.</p></section><section class="front"><h1>MỤC LỤC</h1><div id="toc"></div></section><section class="front figure-list"><h1>DANH MỤC HÌNH</h1><div id="figures"></div></section><section class="front"><h1>DANH MỤC BẢNG VÀ TỪ VIẾT TẮT</h1><p>Bảng 2.1: quyền hạn agent. Bảng 3.1: contracts. Bảng 4.1: feature dictionary. Bảng 4.2: RL actions. Bảng KQ.1–KQ.7: prediction, RAG, MAS, RL, safety, LLM summary và từng câu hỏi.</p><p>MAS: Multi-Agent System; DL: Deep Learning; KG: Knowledge Graph; RAG: Retrieval-Augmented Generation; RL: Reinforcement Learning; MDP: Markov Decision Process; LLM: Large Language Model; BCE: Binary Cross Entropy; AP: Average Precision; MRR: Mean Reciprocal Rank; ERD: Entity Relationship Diagram; NIDDK: National Institute of Diabetes and Digestive and Kidney Diseases.</p><p>Mục lục PDF được điền số trang từ chính PDF đã render; PDF và DOCX dùng cùng tám file Markdown, nhưng hai bộ máy dàn trang có thể phân trang khác nhau. DOCX có Word TOC field riêng. PDF được xuất bằng Chromium sau khi Word automation không hoàn tất bước export.</p></section>'''
document=f'<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Diabetes MAS — báo cáo cuối kỳ</title><base href="{OUT.as_uri()}/"><style>{css}</style></head><body>{cover}{front}<main>{converted}</main></body></html>'
(OUT/'report_print.html').write_text(document,encoding='utf-8')
subprocess.run(['node',str(ROOT/'scripts/render_report_pdf.cjs')],cwd=ROOT,check=True)
